{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE redtape_db.Maplemonk.redtape_db_amazon_margin_fact_items as SELECT AMZ.* ,SHIPPING_CHARGE ,ROUND((SHIPPING_CHARGE * ((100 - \"COURIER_RET%\")/100) / ((100 - \"COURIER_RET%\" - \"CUSTOMER_RET%\")/100)) * 80/100,2) AS TOTAL_SHIPPING_CHARGE ,STANDARD ,ROUND((STANDARD * ((100 - \"COURIER_RET%\")/100) / ((100 - \"COURIER_RET%\" - \"CUSTOMER_RET%\")/100)) - STANDARD,2) AS REFUND_COMMISSION ,CLOSING_FEES ,ROUND((CLOSING_FEES * ((100 - \"COURIER_RET%\")/100) / ((100 - \"COURIER_RET%\" - \"CUSTOMER_RET%\")/100)) / 100,2) AS TOTAL_CLOSING_FEES ,TECH_FEE ,ROUND((TECH_FEE * ((100 - \"COURIER_RET%\")/100) / ((100 - \"COURIER_RET%\" - \"CUSTOMER_RET%\")/100)) / 100,2) AS TOTAL_TECH_FEE ,ROUND(5 / ((100 - \"COURIER_RET%\" - \"CUSTOMER_RET%\")/100),2) PACKING ,ROUND(SALE_VALUE *(3/100),2) ADVT ,ROUND(SALE_VALUE *(7.5/100),2) COMMON ,ROUND((COALESCE(COMMISSION_VALUE,0) + COALESCE(TOTAL_SHIPPING_CHARGE,0) + COALESCE(REFUND_COMMISSION,0) + COALESCE(TOTAL_CLOSING_FEES,0) + COALESCE(TOTAL_TECH_FEE,0) + COALESCE(PACKING,0) + COALESCE(ADVT,0) + COALESCE(COMMON,0)),2) AS TOTAL_EXPENSES ,ROUND((TOTAL_EXPENSES/NULLIF(SALE_VALUE,0)),2) AS \"EXPENSES_%\" ,COALESCE((GROSS_MARGIN - TOTAL_EXPENSES),0) AS NET_MARGIN ,ROUND(NET_MARGIN/NULLIF(SALE_VALUE,0),2) \"NET_MARGIN%\" FROM( SELECT COALESCE(B.EAN,REPLACE(REPLACE(A.EANUPC, \'`\', \'\'), \',\', \'\')) EAN, A.SKU, A.GENDER, UPPER(A.CATEGORY_NAME) CATEGORY_NAME, A.SAP_CATEGORY, UPPER(A.TYPE) TYPE, UPPER(A.LEVEL) LEVEL, A.FLIPKART_CATEGORY CATEGORY, COALESCE(REGEXP_REPLACE(REPLACE(SKU,\'`\',\'\'), \'-[^-]*$\', \'\'),A.ARTICLES) ARTICLE, A.LENGTH AS LENGTH_CM, A.HEIGHT AS HEIGHT_CM, A.WIDTH AS WIDTH_CM, A.WEIGHT, ROUND(COALESCE(TRY_TO_DOUBLE(A.WEIGHT),0) / 1000.0,2) AS WEIGHT_KG, ROUND(( COALESCE(TRY_TO_DOUBLE(A.LENGTH),0) * COALESCE(TRY_TO_DOUBLE(A.HEIGHT),0) * COALESCE(TRY_TO_DOUBLE(A.WIDTH),0)) / 5000.0,2) AS VOLUME_WEIGHT, CASE WHEN VOLUME_WEIGHT > WEIGHT_KG THEN VOLUME_WEIGHT ELSE WEIGHT_KG END AS CHARGEABLE_WEIGHT, CASE WHEN CHARGEABLE_WEIGHT <= 0.5 THEN 0.5 WHEN CHARGEABLE_WEIGHT <= 1 THEN 1 WHEN CHARGEABLE_WEIGHT <= 1.5 THEN 1.5 WHEN CHARGEABLE_WEIGHT <= 2 THEN 2 WHEN CHARGEABLE_WEIGHT <= 2.5 THEN 2.5 WHEN CHARGEABLE_WEIGHT <= 3 THEN 3 ELSE 3.1 END AS WEIGHT_SLAB_HELPER, 70.0 AS \"DISCOUNT_%\", CASE WHEN \"Courier Return %\" IS NULL OR \"Courier Return %\" = 0 THEN 25 ELSE ROUND(\"Courier Return %\", 1) END AS \"COURIER_RET%\", CASE WHEN \"Customer Return %\" IS NULL OR \"Customer Return %\" = 0 THEN 11 ELSE ROUND(\"Customer Return %\", 1)END AS \"CUSTOMER_RET%\", CAST(REPLACE(A.COST, \',\', \'\') AS FLOAT) AS COST, CAST(REPLACE(A.MRP, \',\', \'\') AS FLOAT) AS MRP, ROUND(COALESCE(MRP,0) / NULLIF(COST, 0),2) AS MULTIPLE, ROUND(COALESCE(MRP,0) - (COALESCE(MRP,0) * \"DISCOUNT_%\" / 100),2) AS BILL_VALUE, CASE WHEN BILL_VALUE < 2625 THEN 5 ELSE 18 END AS \"GST_%\", ROUND((BILL_VALUE * 100 / NULLIF(100 + \"GST_%\", 0)),2) AS SALE_VALUE, ROUND(COALESCE((SALE_VALUE - COST),0),2) AS GROSS_MARGIN, ROUND(GROSS_MARGIN / NULLIF(SALE_VALUE, 0), 2) AS \"GROSS_MARGIN%\", COMMISSION, ROUND(BILL_VALUE * (COMMISSION/100),2) AS COMMISSION_VALUE, AVAILABLE_QUANTITY FROM MAPLEMONK.REDTAPE_DB_MARGIN_PRODUCT_MASTER A LEFT JOIN ( SELECT * FROM ( SELECT \"Report Generated Date\"::DATE AS FIRST_DATE, REPLACE(EAN, \'`\', \'\') AS EAN, SUM(\"Available Quantity\") AS AVAILABLE_QUANTITY FROM REDTAPE_DB.MAPLEMONK.EASYECOM_REDTAPE_INVENTORY_SNAPSHOT WHERE \"Report Generated Date\" IS NOT NULL GROUP BY 1,2) QUALIFY ROW_NUMBER() OVER(PARTITION BY EAN ORDER BY FIRST_DATE DESC) = 1) B ON REPLACE(A.EANUPC, \'`\', \'\') = REPLACE(B.EAN, \'`\', \'\') LEFT JOIN( select \"TYPE 2\" TYPE ,GENDER ,\"Courier Return %\" ,\"Customer Return %\" from MAPLEMONK.REDTAPE_AMAZON_MARGIN_RETURN__ where UPPER(GENDER) != \'ALL\') CR ON UPPER(REPLACE(TRIM(A.TYPE), \' \', \'\')) = UPPER(REPLACE(TRIM(CR.TYPE), \' \', \'\')) AND UPPER(TRIM(A.GENDER)) = UPPER(TRIM(CR.GENDER)) LEFT JOIN( SELECT DISTINCT UPPER(\"SAP Category\") SAP_CATEGORY ,COMMISSION FROM MAPLEMONK.REDTAPE_AMAZON_MARGIN_COMMISSION ) C ON UPPER(TRIM(A.SAP_CATEGORY)) = UPPER(TRIM(C.SAP_CATEGORY)) ) AMZ LEFT JOIN ( SELECT LOWER_WEIGHT, UPPER_WEIGHT, \"Shipping charge\" SHIPPING_CHARGE FROM MAPLEMONK.REDTAPE_AMAZON_MARGIN_SHIPPING_CHARGES ) SC ON AMZ.CHARGEABLE_WEIGHT BETWEEN SC.LOWER_WEIGHT AND SC.UPPER_WEIGHT LEFT JOIN ( SELECT TRY_TO_NUMBER(REPLACE(LOWER_PRICE, \',\', \'\')) AS LOWER_PRICE, TRY_TO_NUMBER(REPLACE(UPPER_PRICE, \',\', \'\')) AS UPPER_PRICE, STANDARD FROM MAPLEMONK.REDTAPE_AMAZON_MARGIN_REFUND_FEE ) RF ON AMZ.BILL_VALUE BETWEEN RF.LOWER_PRICE AND RF.UPPER_PRICE LEFT JOIN( SELECT TRY_TO_NUMBER(REPLACE(LOWER_PRICE, \',\', \'\')) AS LOWER_PRICE, TRY_TO_NUMBER(REPLACE(UPPER_PRICE, \',\', \'\')) AS UPPER_PRICE, \"Closing Fees\" CLOSING_FEES FROM MAPLEMONK.REDTAPE_AMAZON_MARGIN_CLOSING_FEE ) CF ON AMZ.BILL_VALUE BETWEEN CF.LOWER_PRICE AND CF.UPPER_PRICE LEFT JOIN( SELECT \"SAP Category\" SAP_CATEGORY, \"Tech Fee\" TECH_FEE FROM MAPLEMONK.REDTAPE_AMAZON_MARGIN_TECH_FEE ) TF ON UPPER(TRIM(AMZ.SAP_CATEGORY)) = UPPER(TRIM(TF.SAP_CATEGORY))",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from REDTAPE_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            